def match_parens(lst):
    """
    Checks if a string is good in a given order.
    """
    stack = []
    for s in lst:
        if s == '(':
            stack.append(s)
        elif s == ')':
            if not stack:
                return False
            stack.pop()
        else:
            return False
    return stack == []
```

