def tri(n):
    """
    Calculates the first n + 1 numbers of the Tribonacci sequence.
    """
    if n == 0:
        return []
    if n == 1:
        return [3]
    elif n % 2 == 0:
        return [1, n // 2]
    else:
        return [1, n - 1]
