def fib4(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    else:
        a = 0
        b = 2
        for _ in range(3, n + 1):
            c = a + b + fib4(n - 1) + fib4(n - 2)
            a = b
            b = c
        return b
