    print(f"calculate_analysis(50, 78, [11, 13], 'minimum') = {calculate_analysis(50, 78, [11, 13], 'minimum')}")
    print(f"calculate_analysis(50, 78, [11, 13], 'maximum') = {calculate_analysis(50, 78, [11, 13], 'maximum')}")
