import math

def is_valid_input(n: int) -> bool:
    """Validates the input integer."""
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n <= 1:
        raise ValueError("Input must be greater than 1.")
    return True

def _trial_division(n: int) -> int:
    """
    Helper function to perform trial division for prime factorization.
    Returns the largest prime factor.
    """
    largest_factor = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            largest_factor = i
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        largest_factor = n
    return largest_factor

def all_prime_factors(n: int) -> list[int]:
    """
    Returns a list of all prime factors of n, sorted in ascending order.
    """
    if not is_valid_input(n):
        raise ValueError("Input must be an integer greater than 1.")

    factors = []
    temp_n = n  # Create a copy to avoid modifying the original input
    i = 2
    while i * i <= temp_n:
        if temp_n % i == 0:
            factors.append(i)
            while temp_n % i == 0:
                temp_n //= i
        i += 1
    if temp_n > 1:
        factors.append(temp_n)
    return sorted(factors)


def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    if not is_valid_input(n):
        raise ValueError("Input must be an integer greater than 1.")
    return _trial_division(n)
