from typing import List, Union

def exchange(lst1: List[Union[int, float]], lst2: List[Union[int, float]]) -> str:
    """
    Determines if it is possible to exchange elements between two lists to make all elements of lst1 even.

    Args:
        lst1: The first list of numbers.
        lst2: The second list of numbers.

    Returns:
        "YES" if it is possible to make all elements of lst1 even by exchanging elements,
        "NO" otherwise.
    """
    try:
        if not isinstance(lst1, list) or not isinstance(lst2, list):
            raise TypeError("Inputs must be lists.")

        if not lst1 or not lst2:
            return "NO"  # Handle empty lists

        if not validate_input(lst1, lst2):
            return "NO"

        if can_make_even(lst1, lst2):
            return "YES"
        else:
            return "NO"

    except TypeError as e:
        return error_handler(str(e))
    except ValueError as e:
        return error_handler(str(e))
    except Exception as e:
        return error_handler(f"An unexpected error occurred: {str(e)}")


def validate_input(lst1: List[Union[int, float]], lst2: List[Union[int, float]]) -> bool:
    """
    Validates that both lists contain only numbers (int or float).

    Args:
        lst1: The first list.
        lst2: The second list.

    Returns:
        True if both lists contain only numbers, False otherwise.
    """
    for lst in [lst1, lst2]:
        for item in lst:
            if not isinstance(item, (int, float)):
                raise ValueError("Lists must contain only numbers (int or float).")
    return True


def can_make_even(lst1: List[Union[int, float]], lst2: List[Union[int, float]]) -> bool:
    """
    Helper function to determine if the exchange is possible.
    """
    odd_count_lst1 = sum(1 for x in lst1 if x % 2 != 0)
    even_count_lst2 = sum(1 for x in lst2 if x % 2 == 0)

    return odd_count_lst1 <= even_count_lst2

def error_handler(message: str) -> str:
    """
    Handles and formats error messages.

    Args:
        message: The error message.

    Returns:
        A formatted error message.
    """
    return f"Error: {message}"
