def count_ones(n):
    """Counts the number of 1s in the binary representation of an integer."""
    count = 0
    if n < 0:
        n = abs(n)  # Handle negative numbers using two's complement
        binary_string = bin(n)[3:] # Remove "0b" prefix and handle negative sign
    else:
        binary_string = bin(n)[2:] # Remove "0b" prefix
    for bit in binary_string:
        if bit == '1':
            count += 1
    return count


def sort_array(arr):
    """
    Sorts an array of integers based on the number of ones in their binary representation
    in ascending order. For similar number of ones, sort based on decimal value.
    """
    if not isinstance(arr, list):
        raise TypeError("Input must be a list.")

    if not all(isinstance(x, int) for x in arr):
        raise TypeError("List elements must be integers.")

    return sorted(arr, key=lambda x: (count_ones(x), x))
