import unittest

def Strongest_Extension(class_name, extensions):
    """
    Finds the strongest extension for a given class based on the CAP - SM strength metric.

    Args:
        class_name (str): The name of the class.
        extensions (list of str): A list of potential extension names.

    Returns:
        str: A string in the format "ClassName.StrongestExtensionName".
             Returns "ClassName.None" if the extensions list is empty.
    """

    if not extensions:
        return f"{class_name}.None"

    best_extension = None
    best_strength = float('-inf')  # Initialize with negative infinity

    for extension in extensions:
        cap_count = 0
        sm_count = 0
        for char in extension:
            if 'A' <= char <= 'Z':
                cap_count += 1
            elif 'a' <= char <= 'z':
                sm_count += 1

        strength = cap_count - sm_count

        if strength > best_strength:
            best_strength = strength
            best_extension = extension

    return f"{class_name}.{best_extension}"


class TestStrongestExtension(unittest.TestCase):

    def test_empty_extensions(self):
        self.assertEqual(Strongest_Extension("MyClass", []), "MyClass.None")

    def test_simple_case(self):
        self.assertEqual(Strongest_Extension("my_class", ["AA", "Be", "CC"]), "my_class.AA")

    def test_example_case(self):
        self.assertEqual(Strongest_Extension("Slices", ['SErviNGSliCes', 'Cheese', 'StuFfed']), "Slices.SErviNGSliCes")

