        self.assertEqual(Strongest_Extension("Test", ["AA", "BB", "CC"]), "Test.AA")

    def test_negative_strength(self):
        self.assertEqual(Strongest_Extension("Test", ["abc", "def"]), "Test.abc")

    def test_mixed_case(self):
        self.assertEqual(Strongest_Extension("Test", ["aB", "CdE"]), "Test.CdE")

    def test_special_characters(self):
        self.assertEqual(Strongest_Extension("Test", ["123", "abc"]), "Test.abc")

    def test_empty_extension(self):
        self.assertEqual(Strongest_Extension("Test", [""]), "Test.None") #Handles empty string extension

    def test_same_strength_different_lengths(self):
        self.assertEqual(Strongest_Extension("Test", ["AA", "A"]), "Test.AA")

    def test_all_lowercase(self):
