def solve(s):
    """
    Manipulates a string based on the rules:
    - Reverses the case of letters.
    - Reverses the string if it contains no letters.
    """
    if not isinstance(s, str):
        return ""  # Or raise a TypeError: raise TypeError("Input must be a string")

    has_letters = False
    for char in s:
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z':
            has_letters = True
            break

    if not has_letters:
        return s[::-1]  # Reverse the string

    result = ""
    for char in s:
        if 'a' <= char <= 'z':
            result += char.upper()
        elif 'A' <= char <= 'Z':
            result += char.lower()
        else:
            result += char
    return result
