import hashlib

class Hasher:
    """
    A class to encapsulate the hashing algorithm.  Allows for easy
    swapping of algorithms in the future.
    """
    def __init__(self, algorithm='md5'):
        self.algorithm = algorithm

    def hash_string(self, text):
        """
        Hashes the given string using the configured algorithm.
        """
        if not isinstance(text, str):
            raise TypeError("Input must be a string")

        if self.algorithm == 'md5':
            return string_to_md5(text)  # Delegate to the function
        elif self.algorithm == 'sha256':
            return hashlib.sha256(text.encode('utf-8')).hexdigest()
        else:
            raise ValueError(f"Unsupported hashing algorithm: {self.algorithm}")


def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    md5_hash = hashlib.md5(text.encode('utf-8'))
    return md5_hash.hexdigest()[:-1] # Truncate the last character
