    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a <= 1:
        return False

    factors = []
    d = 2
    temp = a
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)

    if len(factors) != 3:
        return False

    for factor in factors:
        if factor <= 1:
            return False
        for i in range(2, int(factor**0.5) + 1):
            if factor % i == 0:
                return False

    return True
