def match_parens(lst):
    '''
    You are given a list of two strings, both strings consist of open
    parentheses '(' or close parentheses ')' only.
    Your job is to check if it is possible to concatenate the two strings in
    some order, that the resulting string will be good.
    A string S is considered to be good if and only if all parentheses in S
    are balanced. For example: the string '(())()' is good, while the string
    '())' is not.
    Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.

    Examples:
    match_parens(['()(', ')']) == 'Yes'
    match_parens([')', ')']) == 'No'
    '''
    def is_balanced(s):
        """
        Checks if a string of parentheses is balanced.

        Args:
            s: The string to check.

        Returns:
            True if the string is balanced, False otherwise.
        """
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    if not isinstance(lst, list) or len(lst) != 2:
        return "No"  # Or raise an exception: raise ValueError("Input must be a list of two strings.")

    if not all(isinstance(s, str) for s in lst):
        return "No"  # Or raise an exception: raise ValueError("Input list must contain strings.")

    if not all(all(c in '()' for c in s) for s in lst):
        return "No" # Or raise an exception: raise ValueError("Strings must contain only '(' and ')' characters.")

    str1 = lst[0]
    str2 = lst[1]

    if is_balanced(str1 + str2):
        return "Yes"
    if is_balanced(str2 + str1):
        return "Yes"
    return "No"
