import argparse

def specialFilter(nums):
    """Write a function that takes an array of numbers as input and returns 
    the number of elements in the array that are greater than 10 and both 
    first and last digits of a number are odd (1, 3, 5, 7, 9).
    For example:
    specialFilter([15, -73, 14, -15]) => 1 
    specialFilter([33, -2, -3, 45, 21, 109]) => 2
    """
    count = 0
    for num in nums:
        if num > 10:
            num_str = str(abs(num))  # Handle negative numbers
            if len(num_str) > 0 and num_str[0] in '13579' and num_str[-1] in '13579':
                count += 1
    return count

def main():
    parser = argparse.ArgumentParser(description="Filter a list of numbers to find 'special' numbers.")
    parser.add_argument("numbers", nargs='*', type=int, help="List of numbers to filter (space separated)")
    parser.add_argument("-f", "--file", help="Path to a file containing numbers (one per line)")
    args = parser.parse_args()

    numbers = []

    if args.file:
        try:
            with open(args.file, 'r') as f:
                for line in f:
                    try:
                        numbers.append(int(line.strip()))
                    except ValueError:
                        print(f"Error: Invalid input '{line.strip()}' in file. Skipping.")
        except FileNotFoundError:
            print(f"Error: File '{args.file}' not found.")
            return
        except Exception as e:
            print(f"Error reading file: {e}")
            return
    else:
        numbers = args.numbers

    if not all(isinstance(x, int) for x in numbers):
        print("Error: Input must be a list of integers.")
        return

    result = specialFilter(numbers)
    print(f"Number of special numbers: {result}")

if __name__ == "__main__":
    main()
